/**
 * Unified error type for Zephyr core library.
 * All FFI boundary errors use this type for cross-platform compatibility.
 */
public enum AppError {

    
    
    case IoError(String
    )
    case NetworkError(String
    )
    case ConfigError(String
    )
    case CryptoError(String
    )
    case Cancelled
    case ParseError(String
    )
    case UnknownError(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeAppError: FfiConverterRustBuffer {
    typealias SwiftType = AppError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> AppError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .IoError(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .NetworkError(
            try FfiConverterString.read(from: &buf)
            )
        case 3: return .ConfigError(
            try FfiConverterString.read(from: &buf)
            )
        case 4: return .CryptoError(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .Cancelled
        case 6: return .ParseError(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .UnknownError(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: AppError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .IoError(v1):
            writeInt(&buf, Int32(1))
